<script setup>
import{onMounted,reactive,ref}from'vue';import AdminLayout from'../../components/admin/AdminLayout.vue';import{adminJson}from'../../services/adminAuth';const rows=ref([]),editing=ref(null),error=ref(''),form=reactive({title_bn:'',title_en:'',description:'',event_date:'',event_time:'',location:'',is_active:true});async function load(){rows.value=await adminJson('/api/admin/events')}function reset(){editing.value=null;Object.assign(form,{title_bn:'',title_en:'',description:'',event_date:'',event_time:'',location:'',is_active:true})}function edit(i){editing.value=i.id;Object.assign(form,{title_bn:i.title_bn,title_en:i.title_en||'',description:i.description||'',event_date:i.event_date?.slice(0,10),event_time:i.event_time?.slice(0,5)||'',location:i.location||'',is_active:i.is_active})}async function save(){try{await adminJson(editing.value?`/api/admin/events/${editing.value}`:'/api/admin/events',{method:editing.value?'PUT':'POST',body:JSON.stringify(form)});reset();await load()}catch(e){error.value=e.message}}async function remove(i){if(confirm('ইভেন্টটি মুছে ফেলবেন?')){await adminJson(`/api/admin/events/${i.id}`,{method:'DELETE'});await load()}}onMounted(load)
</script>
<template><AdminLayout><div class="admin-title"><div><p>বিহার ব্যবস্থাপনা</p><h1>ইভেন্ট</h1></div></div><div class="management-grid"><section class="panel"><div class="panel-head"><h2>ইভেন্ট তালিকা</h2></div><div class="record-list"><article v-for="item in rows" :key="item.id"><div class="date-badge">{{new Date(item.event_date).toLocaleDateString('bn-BD',{day:'2-digit',month:'short'})}}</div><div><b>{{item.title_bn}}</b><small>{{item.location||'স্থান উল্লেখ নেই'}}</small></div><span class="status-pill" :class="item.is_active?'confirmed':'rejected'">{{item.is_active?'প্রকাশিত':'খসড়া'}}</span><button @click="edit(item)">সম্পাদনা</button><button class="danger-text" @click="remove(item)">মুছুন</button></article><div v-if="!rows.length" class="empty compact">কোনো ইভেন্ট নেই।</div></div></section><section class="panel sticky-panel"><div class="panel-head"><h2>{{editing?'ইভেন্ট সম্পাদনা':'নতুন ইভেন্ট'}}</h2></div><form class="management-form" @submit.prevent="save"><label>বাংলা শিরোনাম<input v-model="form.title_bn" required></label><label>ইংরেজি শিরোনাম<input v-model="form.title_en"></label><div class="two-inputs"><label>তারিখ<input v-model="form.event_date" type="date" required></label><label>সময়<input v-model="form.event_time" type="time"></label></div><label>স্থান<input v-model="form.location"></label><label>বিবরণ<textarea v-model="form.description" rows="4"></textarea></label><label class="toggle-label"><input v-model="form.is_active" type="checkbox"> প্রকাশ করুন</label><p v-if="error" class="login-error">{{error}}</p><button class="admin-button">সংরক্ষণ করুন</button><button v-if="editing" type="button" class="secondary-button" @click="reset">বাতিল</button></form></section></div></AdminLayout></template>
